/* ---------------- Generadores ---------------- */
const term=(o,key,role,n,codes)=>({key,role,n:o.n,var:o.var,lv:o.lv?o.lv.slice(0,n):names(o.pre,n),codes:codes||range(n).map(i=>i+1)});
const trEff=(k,size)=>{const sig=Math.random()<0.75;return shuffle(range(k).map(i=>(i-(k-1)/2)*size*(sig?rnd(0.7,1.3):rnd(0,0.15))));};
const nuiEff=(k,size)=>{const on=Math.random()<0.7;return range(k).map(()=>gauss()*size*(on?1:0.1));};
function squares(p,greco){const rp=shuffle(range(p)),cp=shuffle(range(p)),s1=shuffle(range(p)),s2=shuffle(range(p));
  const m2=[0,2,3,1],f1=(i,j)=>p===4?(i^j):(i+j)%p,f2=(i,j)=>p===4?(i^m2[j]):(i+2*j)%p;
  const L1=range(p).map(i=>range(p).map(j=>s1[f1(rp[i],cp[j])])),L2=greco?range(p).map(i=>range(p).map(j=>s2[f2(rp[i],cp[j])])):null;return{L1,L2};}
function genLatin(greco){const b=pickNew(greco?'dcgl':'dcl',greco?B_DCGL:B_DCL),p=pick([4,5]);const {L1,L2}=squares(p,greco);
  const T=[term(b.tr,'tr','tr',p),term(b.row,'row','nui',p),term(b.col,'col','nui',p)];if(greco)T.push(term(b.gr,'gr','nui',p));
  const te=trEff(p,b.eff),re=nuiEff(p,b.reff),ce=nuiEff(p,b.ceff),ge=greco?nuiEff(p,b.geff):null,rows=[];
  for(let i=0;i<p;i++)for(let j=0;j<p;j++){const x=[L1[i][j],i,j];if(greco)x.push(L2[i][j]);
    const m=b.mu+te[x[0]]+re[i]+ce[j]+(greco?ge[x[3]]:0);rows.push({x,y:round(m+gauss()*b.sd,b.resp.dec)});}
  return{design:greco?'dcgl':'dcl',ctx:b.ctx(p),resp:b.resp,T,rows,p,L1,L2};}
function genBIB(){const b=pickNew('dbib',B_DBIB),d={...pick(BIB.filter(x=>x.t<=b.tr.lv.length))},perm=shuffle(range(d.t));
  const bl=shuffle(d.bl.map(s=>s.map(i=>perm[i]).sort((a,c)=>a-c)));const T=[term(b.tr,'tr','tr',d.t),term(b.blk,'blk','nui',d.b)];
  const te=trEff(d.t,b.eff),be=nuiEff(d.b,b.beff),rows=[];bl.forEach((s,j)=>s.forEach(i=>rows.push({x:[i,j],y:round(b.mu+te[i]+be[j]+gauss()*b.sd,b.resp.dec)})));
  return{design:'dbib',ctx:b.ctx(d),resp:b.resp,T,rows,bib:{...d,bl}};}
function genFab(){const b=pickNew('fab',B_FAB),a=b.A.lv.length,bb=b.B.lv.length,r=a*bb>=9?pick([2,3]):pick([2,3,3,4]),sd=b.sd;
  const T=[term(b.A,'A','tr',a),term(b.B,'B','tr',bb)];const onA=Math.random()<0.8,onB=Math.random()<0.7,onAB=Math.random()<0.45;
  const ea=shuffle(range(a).map(i=>(i-(a-1)/2)*sd*(onA?rnd(1.5,3):rnd(0,0.3)))),eb=shuffle(range(bb).map(i=>(i-(bb-1)/2)*sd*(onB?rnd(1.8,3.5):rnd(0,0.3))));
  const eab=range(a).map(()=>range(bb).map(()=>gauss()*sd*(onAB?rnd(1.6,2.6):0.15))),rows=[];
  for(let i=0;i<a;i++)for(let j=0;j<bb;j++)for(let k=0;k<r;k++)rows.push({x:[i,j],y:round(b.mu+ea[i]+eb[j]+eab[i][j]+gauss()*sd,b.resp.dec)});
  return{design:'fab',ctx:b.ctx(r),resp:b.resp,T,rows,r};}
const GEN={dcl:()=>genLatin(false),dcgl:()=>genLatin(true),dbib:genBIB,fab:genFab};

/* ---------------- Álgebra mínima (mínimos cuadrados) ---------------- */
function inv(M){const n=M.length,A=M.map((r,i)=>[...r,...range(n).map(j=>i===j?1:0)]);
  for(let c=0;c<n;c++){let p=c;for(let r=c+1;r<n;r++)if(Math.abs(A[r][c])>Math.abs(A[p][c]))p=r;[A[c],A[p]]=[A[p],A[c]];const d=A[c][c];for(let j=0;j<2*n;j++)A[c][j]/=d;
    for(let r=0;r<n;r++)if(r!==c){const f=A[r][c];if(f)for(let j=0;j<2*n;j++)A[r][j]-=f*A[c][j];}}return A.map(r=>r.slice(n));}
/* codificación de efectos (suma cero): columnas para los niveles 0..L-2; el último nivel vale -1 en todas */
function design(rows,terms){return rows.map(r=>{const v=[1];terms.forEach(t=>{const L=t.L,x=r.x[t.i];for(let l=0;l<L-1;l++)v.push(x===l?1:x===L-1?-1:0);});return v;});}
function ols(rows,terms){const X=design(rows,terms),y=rows.map(r=>r.y),p=X[0].length;const XtX=range(p).map(i=>range(p).map(j=>ST.sum(X.map(x=>x[i]*x[j])))),Xty=range(p).map(i=>ST.sum(X.map((x,k)=>x[i]*y[k])));
  const Ci=inv(XtX),b=Ci.map(r=>ST.sum(r.map((v,j)=>v*Xty[j]))),fit=X.map(x=>ST.sum(x.map((v,j)=>v*b[j])));return{b,Ci,fit,rss:ST.sum(y.map((v,i)=>(v-fit[i])**2)),cols:p};}
/* media marginal estimada de un nivel (promediando los otros términos) */
function emm(fit,terms,ti,l){const c=[1];terms.forEach((t,k)=>{for(let q=0;q<t.L-1;q++)c.push(k===ti?(l===q?1:l===t.L-1?-1:0):0);});
  return{m:ST.sum(c.map((v,j)=>v*fit.b[j])),v:ST.sum(c.map((ci,i)=>ci*ST.sum(c.map((cj,j)=>cj*fit.Ci[i][j]))))};}

/* ---------------- Análisis ---------------- */
function analyze(C){const ys=C.rows.map(r=>r.y),N=ys.length,sumY=ST.sum(ys),sumY2=ST.sum(ys.map(v=>v*v)),gm=sumY/N,fc=sumY*sumY/N,sst=sumY2-fc;
  const A={N,sumY,sumY2,gm,fc,sst},tot=(ti,L)=>range(L).map(l=>ST.sum(C.rows.filter(r=>r.x[ti]===l).map(r=>r.y))),cnt=(ti,L)=>range(L).map(l=>C.rows.filter(r=>r.x[ti]===l).length);
  A.tot=C.T.map((t,i)=>tot(i,t.lv.length));A.cnt=C.T.map((t,i)=>cnt(i,t.lv.length));A.mean=A.tot.map((T,i)=>T.map((v,l)=>v/A.cnt[i][l]));
  const tr=C.T[0];let fitted;
  if(C.design==='dcl'||C.design==='dcgl'){const p=C.p;A.ss=A.tot.map(T=>ST.sum(T.map(v=>v*v))/p-fc);const dfE=(p-1)*(C.design==='dcl'?p-2:p-3),sse=sst-ST.sum(A.ss),mse=sse/dfE;
    A.err={ss:sse,df:dfE,ms:mse};A.rows=C.T.map((t,i)=>{const ms=A.ss[i]/(p-1),F=ms/mse;return{key:t.key,src:t.n,ss:A.ss[i],df:p-1,ms,F,p:ST.pF(F,p-1,dfE)};});
    fitted=C.rows.map(r=>gm+ST.sum(C.T.map((t,i)=>A.mean[i][r.x[i]]-gm)));A.means=A.mean[0];A.n=p;
    A.tukey=ST.tukey(A.means,tr.lv,mse,dfE,p);A.letters=ST.letters(A.means,A.tukey.hsd);}
  else if(C.design==='dbib'){const d=C.bib,{t,k,b,r,l}=d,yi=A.tot[0],yj=A.tot[1];
    A.Q=range(t).map(i=>yi[i]-ST.sum(d.bl.map((s,j)=>s.includes(i)?yj[j]:0))/k);A.tau=A.Q.map(q=>k*q/(l*t));
    const ssTrA=k*ST.sum(A.Q.map(q=>q*q))/(l*t),ssBl=ST.sum(yj.map(v=>v*v))/k-fc,ssTr=ST.sum(yi.map(v=>v*v))/r-fc,ssBlA=ssTrA+ssBl-ssTr,dfE=N-t-b+1,sse=sst-ssTrA-ssBl,mse=sse/dfE;
    A.err={ss:sse,df:dfE,ms:mse};const row=(key,src,ss,df)=>{const ms=ss/df,F=ms/mse;return{key,src,ss,df,ms,F,p:ST.pF(F,df,dfE)};};
    A.rows=[row('tr',tr.n,ssTrA,t-1),row('blk',C.T[1].n,ssBlA,b-1)];A.ssTr=ssTr;A.ssBl=ssBl;A.ssTrA=ssTrA;A.ssBlA=ssBlA;
    A.typeI1=[row('blk',C.T[1].n,ssBl,b-1),row('tr',tr.n,ssTrA,t-1)];A.typeI2=[row('tr',tr.n,ssTr,t-1),row('blk',C.T[1].n,ssBlA,b-1)];
    const terms=[{i:0,L:t},{i:1,L:b}],fit=ols(C.rows,terms);fitted=fit.fit;A.fitCheck=Math.abs(fit.rss-sse);
    A.adj=range(t).map(i=>{const e=emm(fit,terms,0,i);return{m:e.m,se:Math.sqrt(e.v*mse)};});A.adjB=range(b).map(j=>{const e=emm(fit,terms,1,j);return{m:e.m,se:Math.sqrt(e.v*mse)};});
    A.means=A.adj.map(e=>e.m);A.obs=A.mean[0];A.nEff=l*t/k;A.n=r;A.tukey=ST.tukey(A.means,tr.lv,mse,dfE,A.nEff);A.letters=ST.letters(A.means,A.tukey.hsd);}
  else{const a=C.T[0].lv.length,bb=C.T[1].lv.length,r=C.r,cells=[];for(let i=0;i<a;i++)for(let j=0;j<bb;j++){const v=C.rows.filter(x=>x.x[0]===i&&x.x[1]===j).map(x=>x.y);cells.push({i,j,y:v,m:ST.mean(v),sd:ST.sd(v),T:ST.sum(v)});}
    A.cells=cells;const ssA=ST.sum(A.tot[0].map(v=>v*v))/(bb*r)-fc,ssB=ST.sum(A.tot[1].map(v=>v*v))/(a*r)-fc,ssC=ST.sum(cells.map(c=>c.T*c.T))/r-fc,ssAB=ssC-ssA-ssB,sse=sst-ssC,dfE=a*bb*(r-1),mse=sse/dfE;
    A.ssCells=ssC;A.err={ss:sse,df:dfE,ms:mse};const row=(key,src,ss,df)=>{const ms=ss/df,F=ms/mse;return{key,src,ss,df,ms,F,p:ST.pF(F,df,dfE)};};
    A.rows=[row('A',C.T[0].n,ssA,a-1),row('B',C.T[1].n,ssB,bb-1),row('AB',`${C.T[0].n} * ${C.T[1].n}`,ssAB,(a-1)*(bb-1))];
    fitted=C.rows.map(x=>cells.find(c=>c.i===x.x[0]&&c.j===x.x[1]).m);A.levene=r>=3?ST.levene(cells.map(c=>c.y)):null;
    A.tkA=a>=3?ST.tukey(A.mean[0],C.T[0].lv,mse,dfE,bb*r):null;A.ltA=A.tkA?ST.letters(A.mean[0],A.tkA.hsd):null;A.tkB=bb>=3?ST.tukey(A.mean[1],C.T[1].lv,mse,dfE,a*r):null;A.ltB=A.tkB?ST.letters(A.mean[1],A.tkB.hsd):null;
    A.best=cells.reduce((x,y)=>(C.resp.goal==='max'?y.m>x.m:y.m<x.m)?y:x);A.a=a;A.b=bb;}
  A.resid=C.rows.map((r,i)=>r.y-fitted[i]);A.mc={ss:sst-A.err.ss,df:N-1-A.err.df};A.mc.ms=A.mc.ss/A.mc.df;A.mc.F=A.mc.ms/A.err.ms;A.mc.p=ST.pF(A.mc.F,A.mc.df,A.err.df);
  A.R2=1-A.err.ss/sst;A.R2a=1-(A.err.ss/A.err.df)/(sst/(N-1));A.sw=ST.shapiro(A.resid);A.main=C.design==='fab'?A.rows[2]:A.rows[0];
  if(C.design!=='fab'){A.k=tr.lv.length;A.best=A.means.reduce((b,m,i)=>(C.resp.goal==='max'?m>A.means[b]:m<A.means[b])?i:b,0);}
  return A;}

/* ---------------- Presentación ---------------- */
const goalTxt=C=>C.resp.goal==='max'?'mayor':'menor';
const sigTxt=p=>p<ALPHA?`Sig. = ${spP(p)} &lt; 0,05`:`Sig. = ${spP(p)} &gt; 0,05`;
const s3=v=>{const a=Math.abs(v);const d=a===0?0:Math.min(7,Math.max(3,3-Math.floor(Math.log10(a))));return nf(v,d);};
const pTxt=p=>p<0.001?'&lt; 0,001':'= '+nf(p,3);
const nuis=C=>C.T.filter(t=>t.role==='nui');
const cellLab=(C,c)=>`${C.T[0].n} ${C.T[0].lv[c.i]}, ${C.T[1].n} ${C.T[1].lv[c.j]}`;
const groupTag=(lt,i)=>lt.sets.map((s,si)=>s.includes(i)?'abcdefg'[lt.sets.length-1-si]:'').join('');
function tukeyTables(t,means,tk,lt,nEach,k,dfE,dv,mse){const head=[[{t:`(I) ${t.n}`},{t:`(J) ${t.n}`},{t:'Diferencia de medias (I-J)'},{t:'Desv. Error'},{t:'Sig.'},{t:'Intervalo de confianza al 95%',cs:2}],[{t:''},{t:''},{t:''},{t:''},{t:''},{t:'Límite inferior'},{t:'Límite superior'}]];
  const rows=[];for(let i=0;i<k;i++)tk.pairs.filter(p=>p.i===i).forEach((p,idx)=>rows.push([...(idx===0?[{t:t.lv[i],lab:true,rs:k-1}]:[]),L(t.lv[p.j]),Nm(sp(p.d,3)+(p.p<ALPHA?'*':''),`tk.${t.key}.${Math.min(i,p.j)}.${Math.max(i,p.j)}.d`),Nm(sp(p.se,3)),Nm(spP(p.p),`tk.${t.key}.${Math.min(i,p.j)}.${Math.max(i,p.j)}.p`),Nm(sp(p.lo,3)),Nm(sp(p.hi,3))]));
  const o=[spssTable({title:'Comparaciones múltiples',sub:`${dv}<br>HSD Tukey`,head,rows,foot:[{t:`Se basa en las medias observadas.<br>El término de error es la media cuadrática(Error) = ${sp(mse,3)}.`},{t:'*. La diferencia de medias es significativa en el nivel 0,05.'}]})];
  const sets=lt.sets;o.push(spssTable({title:dv.replace('Variable dependiente: ',''),sub:'HSD Tukey<sup>a,b</sup>',head:[[{t:t.n,rs:2},{t:'N',rs:2},{t:'Subconjunto',cs:sets.length}],sets.map((_,i)=>({t:String(i+1)}))],
    rows:[...lt.order.map(i=>[L(t.lv[i]),Nm(String(nEach)),...sets.map((s,si)=>s.includes(i)?Nm(sp(means[i],3),`sub.${t.key}.${si}.${i}`):Nm(''))]),[L('Sig.'),Nm(''),...sets.map(s=>{const ms=s.map(i=>means[i]),q=(Math.max(...ms)-Math.min(...ms))/tk.se;return Nm(spP(1-ST.ptukey(q,k,dfE)));})]],
    foot:[{t:`Se visualizan las medias para los grupos en los subconjuntos homogéneos.<br>Se basa en las medias observadas. El término de error es la media cuadrática(Error) = ${sp(mse,3)}.`},{t:`a. Utiliza el tamaño de la muestra de la media armónica = ${sp(nEach,3)}.`},{t:'b. Alfa = 0,05.'}]}));return o;}
function spssOutput(C,A){const o=[],dv=`Variable dependiente: ${C.resp.n} (${C.resp.u})`;
  o.push(spssTable({title:'Factores inter-sujetos',head:[[{t:''},{t:''},{t:'Etiqueta de valor'},{t:'N'}]],rows:C.T.flatMap((t,ti)=>t.lv.map((l,i)=>[...(i===0?[{t:t.n,lab:true,rs:t.lv.length}]:[]),Nm(String(t.codes[i])),L(l),Nm(String(A.cnt[ti][i]),'fis.n')]))}));
  if(C.design==='fab'){o.push(spssTable({title:'Estadísticos descriptivos',sub:dv,head:[[{t:C.T[0].n},{t:C.T[1].n},{t:'Media'},{t:'Desv. Desviación'},{t:'N'}]],rows:A.cells.map((c,ci)=>[L(C.T[0].lv[c.i]),L(C.T[1].lv[c.j]),Nm(sp(c.m,4),`cell.m.${ci}`),Nm(sp(c.sd,4)),Nm(String(c.y.length))])}));
    if(A.levene)o.push(spssTable({title:'Prueba de igualdad de Levene de varianzas de error<sup>a</sup>',sub:dv,head:[[{t:''},{t:'Estadístico de Levene'},{t:'gl1'},{t:'gl2'},{t:'Sig.'}]],rows:[[L('Se basa en la media'),Nm(sp(A.levene.F,3),'lev.f'),Nm(String(A.levene.d1)),Nm(String(A.levene.d2)),Nm(spP(A.levene.p),'lev.p')]],foot:[{t:'Prueba la hipótesis nula de que la varianza de error de la variable dependiente es igual entre grupos.'}]}));}
  const rows=[[L('Modelo corregido'),Nm(sp(A.mc.ss,3)+'<sup>a</sup>','an.mc.ss'),Nm(String(A.mc.df)),Nm(sp(A.mc.ms,3)),Nm(sp(A.mc.F,3)),Nm(spP(A.mc.p),'an.mc.p')],
    [L('Intersección'),Nm(sp(A.fc,3)),Nm('1'),Nm(sp(A.fc,3)),Nm(sp(A.fc/A.err.ms,3)),Nm(spP(ST.pF(A.fc/A.err.ms,1,A.err.df)),'an.int.p')],
    ...A.rows.map(r=>[L(r.src),Nm(sp(r.ss,3),`an.${r.key}.ss`),Nm(String(r.df),`an.${r.key}.df`),Nm(sp(r.ms,3),`an.${r.key}.ms`),Nm(sp(r.F,3),`an.${r.key}.f`),Nm(spP(r.p),`an.${r.key}.p`)]),
    [L('Error'),Nm(sp(A.err.ss,3),'an.err.ss'),Nm(String(A.err.df),'an.err.df'),Nm(sp(A.err.ms,3),'an.err.ms'),Nm(''),Nm('')],
    [L('Total'),Nm(sp(A.sumY2,3)),Nm(String(A.N)),Nm(''),Nm(''),Nm('')],[L('Total corregido'),Nm(sp(A.sst,3),'an.tot.ss'),Nm(String(A.N-1),'an.tot.df'),Nm(''),Nm(''),Nm('')]];
  o.push(spssTable({title:'Pruebas de efectos inter-sujetos',sub:dv,head:[[{t:'Origen'},{t:'Tipo III de suma de cuadrados'},{t:'gl'},{t:'Media cuadrática'},{t:'F'},{t:'Sig.'}]],rows,foot:[{t:`a. R al cuadrado = ${sp(A.R2,3)} (R al cuadrado ajustada = ${sp(A.R2a,3)})`,k:'r2'}]}));
  o.push(spssTable({title:'Pruebas de normalidad',head:[[{t:'',rs:2},{t:'Shapiro-Wilk',cs:3}],[{t:'Estadístico'},{t:'gl'},{t:'Sig.'}]],rows:[[L(`Residuo para ${C.resp.var}`),Nm(sp(A.sw.W,3),'sw.w'),Nm(String(A.N)),Nm(spP(A.sw.p),'sw.p')]]}));
  if(C.design==='dbib'){const tc=tcrit(A.err.df);
    [[0,A.adj],[1,A.adjB]].forEach(([ti,E])=>{const t=C.T[ti];o.push(spssTable({title:`Medias marginales estimadas: ${t.n}`,sub:dv,head:[[{t:t.n,rs:2},{t:'Media',rs:2},{t:'Desv. Error',rs:2},{t:'Intervalo de confianza al 95%',cs:2}],[{t:'Límite inferior'},{t:'Límite superior'}]],
      rows:E.map((e,i)=>[L(t.lv[i]),Nm(sp(e.m,3),`em.${t.key}.${i}`),Nm(sp(e.se,3)),Nm(sp(e.m-tc*e.se,3)),Nm(sp(e.m+tc*e.se,3))]),foot:[{t:'Son las medias <b>ajustadas</b>: cada una se corrige por los bloques (o los tratamientos) en los que no apareció.'}]}));});}
  if(C.design==='dcl'||C.design==='dcgl')o.push(...tukeyTables(C.T[0],A.means,A.tukey,A.letters,C.p,A.k,A.err.df,dv,A.err.ms));
  if(C.design==='fab'){if(A.tkA)o.push(...tukeyTables(C.T[0],A.mean[0],A.tkA,A.ltA,A.b*C.r,A.a,A.err.df,dv,A.err.ms));if(A.tkB)o.push(...tukeyTables(C.T[1],A.mean[1],A.tkB,A.ltB,A.a*C.r,A.b,A.err.df,dv,A.err.ms));
    if(!A.tkA||!A.tkB)o.push(`<p class="note spss-note">${[A.tkA?null:C.T[0],A.tkB?null:C.T[1]].filter(Boolean).map(t=>`No se realizan pruebas post hoc para <b>${t.n}</b> porque hay menos de tres grupos.`).join(' ')}</p>`);}
  return o;}
/* t crítico bilateral 95 % por bisección (sin depender de otra función) */
function tcrit(df){const pt=t=>ST.ibeta(df/(df+t*t),df/2,0.5);let lo=0,hi=50;for(let i=0;i<60;i++){const m=(lo+hi)/2;if(pt(m)>0.05)lo=m;else hi=m;}return(lo+hi)/2;}

/* Gráficos */
function profileAB(C,A,W){const a=A.a,b=A.b,all=A.cells.map(c=>c.m),lo=Math.min(...all),hi=Math.max(...all),pad=(hi-lo)*0.25||1;
  const curves=range(b).map(j=>({pts:range(a).map(i=>[i,A.cells.find(c=>c.i===i&&c.j===j).m]),cls:'s'+j}));
  return chart({W,H:250,xmin:-0.3,xmax:a-0.7,ymin:lo-pad,ymax:hi+pad,xticks:range(a),xfmt:v=>C.T[0].lv[v]||'',xlabel:C.T[0].n,curves,points:curves.flatMap((c,j)=>c.pts.map(q=>({x:q[0],y:q[1],cls:'sc s'+j}))),ml:58,yfmt:v=>nf(v,2)})
   +`<div class="legend">${range(b).map(j=>`<span><i class="lg s${j}"></i>${C.T[1].n}: ${C.T[1].lv[j]}</span>`).join('')}</div>`;}
function meansChart(t,series,W,yl){const all=series.flatMap(s=>s.v),lo=Math.min(...all),hi=Math.max(...all),pad=(hi-lo)*0.25||1,k=t.lv.length;
  return chart({W,H:230,xmin:-0.5,xmax:k-0.5,ymin:lo-pad,ymax:hi+pad,xticks:range(k),xfmt:v=>t.lv[v]||'',xlabel:t.n,curves:series.map((s,si)=>({pts:s.v.map((v,i)=>[i,v]),cls:'s'+si+(s.dash?' dash':'')})),points:series.flatMap((s,si)=>s.v.map((v,i)=>({x:i,y:v,cls:'sc s'+si}))),ml:58,yfmt:v=>nf(v,2)})
   +`<div class="legend">${series.map((s,si)=>`<span><i class="lg s${si}"></i>${s.n}</span>`).join('')}</div>`;}

